"""Same-direction traffic and entrance lanes with authored solid white separator."""
import xml.etree.ElementTree as ET

SEPARATOR={'y_m':-3.5,'x_min_m':-60,'x_max_m':60,'form':'solid','color':'white',
    'inner_lane_id':-1,'outer_lane_id':-2}


def open_drive():
    root=ET.Element('OpenDRIVE')
    ET.SubElement(root,'header',revMajor='1',revMinor='4',name='C245532 controlled-access lane draft',version='1',date='2026-11-23',north='20',south='-20',east='60',west='-60',vendor='worker')
    road=ET.SubElement(root,'road',id='1',name='eastbound controlled-access highway draft',length='120',junction='-1')
    ET.SubElement(road,'link');ET.SubElement(ET.SubElement(road,'type',s='0',type='motorway'),'speed',max='55',unit='mph')
    geometry=ET.SubElement(ET.SubElement(road,'planView'),'geometry',s='0',x='-60',y='0',hdg='0',length='120')
    ET.SubElement(geometry,'line');ET.SubElement(ET.SubElement(road,'elevationProfile'),'elevation',s='0',a='0',b='0',c='0',d='0')
    section=ET.SubElement(ET.SubElement(road,'lanes'),'laneSection',s='0');ET.SubElement(section,'left')
    center=ET.SubElement(section,'center');ET.SubElement(center,'lane',id='0',type='none',level='false')
    right=ET.SubElement(section,'right')
    for lane_id,name in ((-1,'marked traffic lane'),(-2,'entrance lane')):
        lane=ET.SubElement(right,'lane',id=str(lane_id),type='driving',level='false')
        ET.SubElement(lane,'width',sOffset='0',a='3.5',b='0',c='0',d='0')
        ET.SubElement(lane,'roadMark',sOffset='0',type='solid',color='white',width='0.15')
        ET.SubElement(lane,'userData',code='lane_function',value=name)
    ET.SubElement(road,'objects');ET.SubElement(road,'signals')
    return ET.tostring(root,encoding='unicode')


def check():
    root=ET.fromstring(open_drive());lanes=root.findall('road/lanes/laneSection/right/lane')
    if len(lanes)!=2 or [x.get('id') for x in lanes]!=['-1','-2']:
        raise ValueError('Two same-direction lanes missing')
    marks=[x.find('roadMark') for x in lanes]
    if any(x.get('type')!='solid' or x.get('color')!='white' for x in marks):
        raise ValueError('Separator form/color differs')
    return {'passed':True,'lane_ids':[-1,-2],'separator':SEPARATOR,
        'public_highway_and_access_authority_reviewed':False,'official_entrance_function_reviewed':False}

"""Original Native entrance-to-traffic lane draft; --check is CARLA-free."""
import argparse
import json
import math
from pathlib import Path
import queue
import subprocess

from layout import SEPARATOR,check as layout_check,open_drive

FRAMES=600
CAMERAS=(('overview',1280,720,0,-18,22,-65),('separator_side',1280,720,0,8,10,-35),
    ('entrance_view',1280,720,-32,-12,7,-28),('traffic_view',1280,720,20,8,9,-30))


def check():
    cfg=json.loads(Path('config.json').read_text())
    if cfg['cell_id']!='C245532' or cfg['law_id']!='NRS-484B-587-2b' or cfg['case_suffix'] not in ('controlled_1','controlled_2'):
        raise ValueError('Exact assignment differs')
    if cfg['duration_s']!=30 or cfg['rate_hz']!=20 or len(CAMERAS)!=4:raise ValueError('Capture policy differs')
    return {'passed':True,'geometry':layout_check(),'frame_count':FRAMES,
        'native_imported':False,'physical_acceptance_claimed':False}


def actor_row(actor):
    transform=actor.get_transform();velocity=actor.get_velocity()
    return {'actor_id':actor.id,'blueprint_id':actor.type_id,
        'center_xy_m':[transform.location.x,transform.location.y],
        'body_xy_m':[[p.x,p.y] for p in actor.bounding_box.get_world_vertices(transform)],
        'velocity_xy_mps':[velocity.x,velocity.y],'speed_mps':math.hypot(velocity.x,velocity.y)}


def execute(output,host,port):
    import carla
    from worker_exchange.native_output import FrameMap
    from worker_exchange.world_restore import snapshot,restore
    cfg=json.loads(Path('config.json').read_text());check();output=Path(output).resolve()
    if output.exists():raise ValueError('Use fresh original Native output')
    client=carla.Client(host,port);client.set_timeout(180)
    old=client.get_world();saved=snapshot(client)
    if old.get_settings().synchronous_mode or any(a.type_id.startswith(('vehicle.','walker.','sensor.','controller.')) for a in old.get_actors()):
        raise RuntimeError('Exclusive idle asynchronous Native world required')
    output.mkdir(parents=True);owned=[];encoders={};queues={};changed=False
    try:
        world=client.generate_opendrive_world(open_drive(),carla.OpendriveGenerationParameters(
            vertex_distance=.5,max_road_length=50,wall_height=0,additional_width=0,
            smooth_junctions=False,enable_mesh_visibility=True,enable_pedestrian_navigation=False))
        changed=True;settings=world.get_settings();settings.synchronous_mode=True
        settings.fixed_delta_seconds=.05;settings.substepping=True
        settings.max_substep_delta_time=.01;settings.max_substeps=10;world.apply_settings(settings)
        mapping=world.get_map()
        for y,lane in ((-5.25,-2),(-1.75,-1)):
            waypoint=mapping.get_waypoint(carla.Location(x=0,y=y,z=1),project_to_road=True,lane_type=carla.LaneType.Driving)
            if waypoint is None or waypoint.road_id!=1 or waypoint.lane_id!=lane:
                raise RuntimeError('Native lane function readback failed')
        bp=world.get_blueprint_library().find('vehicle.tesla.model3')
        ego=world.try_spawn_actor(bp,carla.Transform(carla.Location(x=-42,y=-5.25,z=1.2),carla.Rotation(yaw=0)))
        if ego is None:raise RuntimeError('Original vehicle spawn failed')
        owned.append(ego)
        for name,width,height,x,y,z,pitch in CAMERAS:
            cbp=world.get_blueprint_library().find('sensor.camera.rgb')
            for key,value in (('image_size_x',width),('image_size_y',height),('fov',85),('sensor_tick',.05)):
                cbp.set_attribute(key,str(value))
            sensor=world.spawn_actor(cbp,carla.Transform(carla.Location(x=x,y=y,z=z),carla.Rotation(pitch=pitch)))
            owned.append(sensor);received=queue.Queue();sensor.listen(received.put);queues[name]=received
            encoders[name]=subprocess.Popen(['ffmpeg','-nostdin','-hide_banner','-loglevel','error','-n',
                '-f','rawvideo','-pix_fmt','bgra','-s',f'{width}x{height}','-r','20','-i','-',
                '-frames:v',str(FRAMES),'-c:v','ffv1',str(output/(name+'.mkv'))],stdin=subprocess.PIPE,stderr=subprocess.PIPE)
        with (output/'native-motion.jsonl').open('x') as motion,FrameMap(output/'video_frames.jsonl') as frame_map:
            for index in range(FRAMES):
                lateral=.5 if cfg['case_suffix']=='controlled_2' and 40<=index<180 else 0
                ego.set_target_velocity(carla.Vector3D(x=5 if index<350 else 0,y=lateral,z=0))
                native=world.tick();row=actor_row(ego)
                waypoint=mapping.get_waypoint(carla.Location(x=row['center_xy_m'][0],y=row['center_xy_m'][1],z=1),
                    project_to_road=True,lane_type=carla.LaneType.Driving)
                motion.write(json.dumps({'native_frame':native,'video_frame':index,'time_s':index/20,
                    'source_kind':'original_native','ego':row,
                    'lane_id':waypoint.lane_id if waypoint is not None else None},allow_nan=False)+'\n')
                camera_frames={}
                for name,*_ in CAMERAS:
                    image=queues[name].get(timeout=30)
                    while image.frame<native:image=queues[name].get(timeout=30)
                    if image.frame!=native:raise RuntimeError('Original four-camera join differs')
                    encoders[name].stdin.write(image.raw_data);camera_frames[name]=image.frame
                frame_map.append(native,index/20,camera_native_frames=camera_frames)
        for name,process in encoders.items():
            process.stdin.close();error=process.stderr.read()
            if process.wait(timeout=180) or not (output/(name+'.mkv')).is_file():
                raise RuntimeError('Original FFV1 encoding failed: '+name+error.decode()[-400:])
        (output/'road.xodr').write_text(open_drive())
        (output/'separator-context.json').write_text(json.dumps({'source_kind':'original_native',
            'cell_id':'C245532','separator':SEPARATOR,'public_highway_reviewed':False,
            'legal_controlled_access_reviewed':False,'entrance_lane_function_reviewed':False,
            'official_line_reviewed':False,'emergency_necessity_reviewed':False,
            'subsection_3_conditions_reviewed':False,'vehicle_driver_scope_reviewed':False,
            'shoulder_permission_not_treated_as_crossing_authorization':True},indent=2)+'\n')
        return {'frames':FRAMES,'camera_names':list(queues),
            'controlled_access_authority_unverified':True,'physical_acceptance_claimed':False}
    finally:
        for process in encoders.values():
            if process.poll() is None:process.kill();process.wait()
        for actor in reversed(owned):
            try:
                if hasattr(actor,'stop'):actor.stop()
                actor.destroy()
            except Exception:pass
        if changed:restore(client,saved)


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    parser.add_argument('--output-dir',type=Path);parser.add_argument('--host',default='localhost')
    parser.add_argument('--port',type=int,default=2000);args=parser.parse_args()
    if args.check:print(json.dumps(check()))
    else:
        if args.output_dir is None:parser.error('Original Native output directory required')
        print(json.dumps(execute(args.output_dir,args.host,args.port)))

"""Measure original solid-line geometry and lane transition without legal cutoff."""
import argparse
import hashlib
import json
import math
from pathlib import Path

FRAMES=600
CAMERAS=('overview','separator_side','entrance_view','traffic_view')


def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def rows(path):
    if not path.is_file():raise ValueError('Missing required source: '+path.name)
    data=[json.loads(line) for line in path.read_text().splitlines()]
    if len(data)!=FRAMES:raise ValueError('Original source must contain 600 frames')
    return data


def body_range(points):
    if not isinstance(points,list) or len(points)<4:raise ValueError('Original full-body points missing')
    if any(not isinstance(p,list) or len(p)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in p) for p in points):
        raise ValueError('Original full-body point invalid')
    return min(p[1] for p in points),max(p[1] for p in points)


def measure(attempt):
    attempt=Path(attempt);context_path=attempt/'separator-context.json'
    motion_path=attempt/'native-motion.jsonl';frames_path=attempt/'video_frames.jsonl'
    for path in (context_path,motion_path,frames_path):
        if not path.is_file():raise ValueError('Missing required source: '+path.name)
    context=json.loads(context_path.read_text());sep=context.get('separator')
    if context.get('source_kind')!='original_native' or context.get('cell_id')!='C245532':
        raise ValueError('Original controlled-access source identity differs')
    review_keys=('public_highway_reviewed','legal_controlled_access_reviewed',
        'entrance_lane_function_reviewed','official_line_reviewed')
    if any(type(context.get(key)) is not bool for key in review_keys):
        raise ValueError('Original controlled-access review status missing')
    if not isinstance(sep,dict) or sep.get('form')!='solid' or sep.get('color')!='white' or type(sep.get('y_m')) not in (int,float):
        raise ValueError('Original solid-white separator missing')
    motion,frames=rows(motion_path),rows(frames_path)
    previous=-1;straddle=[];traffic_centers=[];lane_ids=set();last_outer=None
    for index,(row,frame) in enumerate(zip(motion,frames)):
        native=row.get('native_frame')
        if type(native) is not int or native<=previous or frame.get('native_frame')!=native:
            raise ValueError('Original Native frame join differs')
        previous=native
        if row.get('video_frame')!=index or frame.get('video_frame')!=index or abs(row.get('time_s',-1)-index/20)>1e-6 or abs(frame.get('time_s',-1)-index/20)>1e-6:
            raise ValueError('Original video frame/time join differs')
        if frame.get('camera_native_frames')!={name:native for name in CAMERAS}:
            raise ValueError('Original four-camera join differs')
        ego=row.get('ego',{});center=ego.get('center_xy_m')
        if not isinstance(center,list) or len(center)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in center):
            raise ValueError('Original ego center missing')
        ymin,ymax=body_range(ego.get('body_xy_m'))
        if ymin<sep['y_m']<ymax:straddle.append(index)
        if center[1]>sep['y_m']:traffic_centers.append(index)
        lane=row.get('lane_id')
        if lane not in (-1,-2):raise ValueError('Original lane readback differs')
        lane_ids.add(lane)
        if lane==-2:last_outer=index
    for name in CAMERAS:
        if not (attempt/(name+'.mkv')).is_file():raise ValueError('Missing required source: '+name+'.mkv')
    return {'format':'c245532-solid-white-separator-raw-geometry-v1','frame_count':FRAMES,
        'rate_hz':20,'separator':sep,
        'first_body_straddle_frame':straddle[0] if straddle else None,
        'body_straddle_frame_count':len(straddle),
        'first_traffic_side_center_frame':traffic_centers[0] if traffic_centers else None,
        'last_outer_lane_frame':last_outer,'native_lane_ids_seen':sorted(lane_ids),
        'source_context_review_pending':any(context[key] is False for key in review_keys),
        'source_context_review':{key:context[key] for key in review_keys},
        'vehicle_driver_scope_reviewed':context.get('vehicle_driver_scope_reviewed') is True,
        'emergency_necessity_reviewed':context.get('emergency_necessity_reviewed') is True,
        'subsection_3_conditions_reviewed':context.get('subsection_3_conditions_reviewed') is True,
        'shoulder_permission_treated_as_crossing_authorization':False,
        'statutory_crossing_cutoff_adopted':False,'crossing_verdict':'unresolved',
        'legal_verdict_claimed':False,'physical_acceptance_claimed':False,
        'source_sha256':{p.name:sha(p) for p in (context_path,motion_path,frames_path)},
        'camera_video_sha256':{name:sha(attempt/(name+'.mkv')) for name in CAMERAS}}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
    if args.output.exists():raise ValueError('Use fresh measurement output')
    value=measure(args.attempt);args.output.write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')
    print(json.dumps({'body_straddle_frame_count':value['body_straddle_frame_count'],
        'first_traffic_side_center_frame':value['first_traffic_side_center_frame'],
        'crossing_verdict':'unresolved'}))


if __name__=='__main__':main()

